# =====================================================================
#  logistics.map - phishing phrases for shipping, freight and customs
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake bill of lading / airway bill downloads, shipment held
#           at customs, customs duty and release fees, courier
#           impersonation (DHL, FedEx, UPS, TNT, Maersk, MSC, CMA CGM),
#           address confirmation, demurrage / port charges, failed
#           delivery and redelivery fees
#
#  Avoided: "packing list attached", "commercial invoice", "arrival
#           notice", "ETA", "telex release", because freight companies
#           exchange real ones every day.
# =====================================================================

# ===== English =====
# Fake shipping documents
/(view|download|open|access)\s+(the\s+)?(original\s+)?(bill\s+of\s+lading|b\/l\s+(copy|draft)|airway\s+bill|awb\s+copy|shipping\s+documents?)\s+(here|below|online|now)/i
/(shipping|shipment)\s+documents?\s+(are\s+|is\s+)?(ready|available)\s+(for\s+download|online|via\s+the\s+link)/i
/(draft|original)\s+b\/l\s+(for\s+your\s+)?(confirmation|approval)\s+(via|through|at)\s+(the\s+)?link/i
# Customs
/(your\s+)?(shipment|parcel|package|consignment)\s+(is\s+)?(held|on\s+hold|detained|stopped)\s+(at|by)\s+customs/i
/customs\s+(duty|fee|clearance\s+fee|charges?)\s+(must\s+be\s+paid|is\s+required|outstanding|unpaid|pending)/i
/pay\s+(the\s+)?(customs|import)\s+(duty|fee|tax)\s+to\s+(release|receive|clear)/i
# Courier impersonation
/(dhl|fedex|ups|tnt|usps|aramex|dpd|gls)\s+(express\s+)?(shipment|delivery|parcel)\s+(notification|alert|on\s+hold|suspended|failed)/i
/(maersk|msc|cma\s+cgm|hapag-?lloyd|cosco|evergreen|one\s+line)\s+(shipment|booking|container|document)\s+(notification|update|alert|on\s+hold)/i
/(we\s+)?(attempted|tried)\s+to\s+deliver\s+your\s+(shipment|parcel|package)/i
/(confirm|update|verify)\s+your\s+(delivery|shipping)\s+address\s+(to|within|for)/i
/(incomplete|incorrect|invalid)\s+(delivery\s+)?address/i
/(re-?delivery|redelivery|storage)\s+fee\s+(of\s+\S+\s+)?(is\s+)?(required|due|pending)/i
# Port / container charges
/(demurrage|detention|port|terminal)\s+(charges?|fees?)\s+(are\s+|is\s+)?(due|overdue|outstanding|unpaid)/i
/container\s+(is\s+)?(held|on\s+hold|blocked)\s+(pending|until)\s+(payment|release)/i
/(freight|shipment)\s+(payment|invoice)\s+(is\s+)?(overdue|outstanding)\s+(to|before)\s+release/i

